#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#include "KS/SRC/ks/FEMenu_shared.h"
#undef KELLY_DECOMP_FULL_FEMENU_ENTRY

enum game_mode_t
{
    GAME_MODE_CAREER,
    GAME_MODE_FREESURF_INFINITE
};

class game
{
public:
    game_mode_t get_game_mode() const;
};

extern game *g_game_ptr;

class PauseMenuSystem : public FEMenuSystem
{
public:
    bool draw;
    bool replay_mode;
    bool end_level;
    int pause_controller;
    int pause_player;
};

class PauseMenuClass : public FEMenu
{
public:
    PauseMenuSystem *sys;
    FEMenuEntry *goals;
    FEMenuEntry *tip;
    FEMenuEntry *options;
    FEMenuEntry *trickbook;
    FEMenuEntry *returnFE;
    virtual void OnActivate();
};

void PauseMenuClass::OnActivate()
{
    FEMenuEntry * oldHigh;

    goals->Disable(g_game_ptr->get_game_mode() != GAME_MODE_CAREER);
    tip->Disable(g_game_ptr->get_game_mode() != GAME_MODE_CAREER);
    trickbook->Disable( sys->pause_player == -1 );
    options->Disable( sys->pause_player == -1 );
    returnFE->Disable(g_game_ptr->get_game_mode() != GAME_MODE_FREESURF_INFINITE);

    // Reposition entries.
    oldHigh = highlighted;
    Init();
    if (oldHigh && !oldHigh->GetDisable())
        setHigh(oldHigh, false);
    else
        HighlightDefault();

    //FEMenu::OnActivate();
}
